using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (!EditorApplication.isPlaying)
                throw new Exception("Play required");
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r103/route-profile");
            if (!s.Load())
                throw new Exception("Private completed route save required");
            s.ClosePage();
            EditorApplication.delayCall += () => ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/final-table-prompt.png");
            r.Log("Label-only fixture: API loads completed route position. Not traversal evidence.");
        }
    }
}

